#!/usr/bin/env bash
# ci#756: restore the tracked, build-generated artifacts the dev stack rewrites,
# so a local `docker compose up`/rebuild never leaves them dirty and blocking a
# `git switch`/`git checkout`.
#
# Two tracked files are regenerated by the development tooling:
#   * integrations.lock.json      - `openchat-integrations prepare` re-pins it to
#                                   the local integration checkouts, which drift
#                                   ahead of the committed lock.
#   * backend/server/swagger.json - `swag init` is copied over it on every backend
#                                   rebuild (it is embedded via go:embed, so the
#                                   build needs a file there).
#
# Restoring the worktree copy to HEAD keeps the developer's branch state intact;
# the running containers already read the freshly generated copies they need.
# Only the worktree is touched (the index staged by the developer is preserved),
# and only files that are actually tracked are restored.
set -euo pipefail

REPO_ROOT="$(git -C "$(dirname "${BASH_SOURCE[0]}")/../.." rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "${REPO_ROOT:-}" ]; then
  exit 0
fi

# The container may run as a different uid than the bind-mounted checkout owner
# (the backend dev image runs as root), which git rejects as "dubious ownership".
for path in integrations.lock.json backend/server/swagger.json; do
  if git -c safe.directory='*' -C "$REPO_ROOT" ls-files --error-unmatch "$path" >/dev/null 2>&1; then
    git -c safe.directory='*' -C "$REPO_ROOT" restore --source=HEAD --worktree -- "$path" 2>/dev/null \
      || git -c safe.directory='*' -C "$REPO_ROOT" checkout -- "$path" 2>/dev/null \
      || true
  fi
done
